            {
                "heading": "Kenapa ada SELinux padahal sudah ada izin berkas",
                "body": [
                    "Izin rwx dari materi Izin Berkas & Kepemilikan termasuk jenis",
                    "Discretionary Access Control. Artinya pemilik berkas yang memutuskan",
                    "siapa boleh apa. Kelemahannya, kalau sebuah program dibajak, si",
                    "pembajak dapat semua hak pengguna yang menjalankan program itu.",
                    "",
                    "Contohnya server web, yang berjalan sebagai pengguna apache. Kalau",
                    "aplikasi webnya punya celah, penyerang bisa membaca semua yang bisa",
                    "dibaca apache. Itu termasuk berkas yang nggak ada hubungannya dengan",
                    "web.",
                    "",
                    "SELinux termasuk jenis Mandatory Access Control. Di sini yang",
                    "memutuskan adalah kebijakan sistem, dan pemilik berkas nggak bisa",
                    "membatalkannya. Pertanyaan yang dijawab SELinux juga lain. Izin rwx",
                    "bertanya \"kamu siapa?\". SELinux bertanya \"proses jenis ini boleh",
                    "menyentuh berkas jenis apa?\".",
                    "",
                    "Jadi walaupun apache boleh membaca sebuah berkas menurut rwx, SELinux",
                    "tetap menolak kalau berkas itu bukan jenis yang boleh disentuh proses",
                    "web. Sebuah akses baru jalan kalau kedua lapisan sama-sama",
                    "mengizinkan.",
                    "",
                    "Jangan matikan SELinux. Di Fedora, SELinux sudah aktif dalam mode",
                    "Enforcing sejak instalasi. Kalau ada tutorial yang menyuruh \"setenforce",
                    "0 supaya berhasil\", tutorial itu sedang mengajarimu melepas rem karena",
                    "malas belajar mengemudi.",
                    "",
                    "Cara melihat keadaan SELinux di mesinmu:",
                ],
                "code": "getenforce\nsestatus\nsestatus -v\ncat /etc/selinux/config",
            },
            {
                "heading": "Tiga mode",
                "body": [
                    "  Enforcing   pelanggaran DITOLAK dan dicatat. Ini yang benar.",
                    "  Permissive  pelanggaran DIIZINKAN tapi tetap dicatat. Mode",
                    "              DIAGNOSIS, bukan mode produksi.",
                    "  Disabled    SELinux mati total.",
                    "",
                    "Mode permissive berguna untuk mencari penyebab masalah. Kalau kamu",
                    "curiga SELinux yang bikin sesuatu gagal, pindah ke permissive",
                    "sebentar. Kalau masalahnya hilang, berarti SELinux memang penyebabnya.",
                    "Log-nya sekarang juga berisi persis apa yang perlu diizinkan. Perbaiki",
                    "izinnya, lalu kembali ke enforcing.",
                    "",
                    "Perubahan lewat setenforce cuma sementara dan hilang saat reboot.",
                    "Supaya permanen, kamu harus menyunting /etc/selinux/config.",
                ],
                "code": "sudo setenforce 0\nsudo setenforce 1\ngetenforce\nsudo sed -i 's/^SELINUX=.*/SELINUX=permissive/' /etc/selinux/config",
            },
